/* ---------- Supabase'den onaylı özel etkinlikleri çek ---------- */
/* Supabase'den onaylı özel etkinlikler burada birikir (ozelEtkinlikleriYukle doldurur).
   Başlangıçta boş: kod kapısıyla girilse bile render bu diziyi güvenle okur. */
var OZEL_ETKINLIKLER = [];

function seviyeleriCoz(seviyeler) {
  var s = [], k = [], arac = false;
  try { var arr = typeof seviyeler === 'string' ? JSON.parse(seviyeler) : (seviyeler || []); } catch (e) { var arr = []; }
  arr.forEach(function (sv) {
    if (sv === 'arac') { arac = true; return; }
    var m;
    if ((m = sv.match(/^s(\d)$/))) s.push(parseInt(m[1], 10));
    else if ((m = sv.match(/^i(\d)$/))) k.push(parseInt(m[1], 10));
  });
  return { siniflar: s, kategoriler: k, ogretmen: arac };
}

/** Her özel etkinlik için benzersiz, çocuk dostu SVG önizleme üretir */
function _ozelHash(str) {
  var h = 5381; for (var i = 0; i < (str||'').length; i++) h = ((h << 5) + h + str.charCodeAt(i)) | 0;
  return Math.abs(h);
}

function ozelOnizlemeSvg(ad, tip, konu) {
  var h = _ozelHash((ad||'') + (tip||'') + (konu||''));
  var palettes = [
    ['#6366f1','#a78bfa'],['#ec4899','#f9a8d4'],['#f59e0b','#fcd34d'],
    ['#10b981','#6ee7b7'],['#ef4444','#fca5a5'],['#8b5cf6','#d8b4fe'],
    ['#0ea5e9','#7dd3fc'],['#f97316','#fdba74'],['#14b8a6','#5eead4'],
    ['#e11d48','#fda4af'],['#7c3aed','#c4b5fd'],['#059669','#a7f3d0'],
    ['#0284c7','#38bdf8'],['#d946ef','#f0abfc'],['#ea580c','#fb923c'],
    ['#4f46e5','#818cf8'],['#0d9488','#2dd4bf'],['#be123c','#fb7185']
  ];
  var ikonlar = ['\u2702','\uD83D\uDD2C','\uD83D\uDE80','\uD83D\uDD2E','\u2B50','\uD83C\uDFAE','\uD83D\uDCBB','\uD83C\uDF1F','\uD83D\uDCD6','\uD83C\uDFB5','\uD83D\uDD35','\uD83D\uDEE0','\uD83D\uDCDA','\u26A1','\uD83C\uDF08','\uD83D\uDCAB','\uD83D\uDCBB','\uD83C\uDFB2','\uD83D\uDCBB','\uD83C\uDFC6'];
  var r = palettes[h % palettes.length];
  var ikon = ikonlar[(h >> 3) % ikonlar.length];
  var baslik = (ad || 'Etkinlik').substring(0, 30);
  var aciklama = (konu || (tip === 'kod' ? 'Kod Etkinliği' : tip === 'dosya' ? 'HTML Dosyası' : 'Drive')).substring(0, 40);
  var ac1 = r[0], ac2 = r[1];
  var sekil1 = '<circle cx="' + (30 + h % 60) + '" cy="' + (20 + h % 40) + '" r="' + (20 + h % 30) + '" fill="rgba(255,255,255,0.08)"/>';
  var sekil2 = '<circle cx="' + (300 + (h>>2) % 80) + '" cy="' + (170 + (h>>2) % 50) + '" r="' + (25 + (h>>2) % 25) + '" fill="rgba(255,255,255,0.06)"/>';
  var sekil3 = '<circle cx="' + (180 + (h>>4) % 60) + '" cy="' + (30 + (h>>4) % 30) + '" r="' + (12 + (h>>4) % 18) + '" fill="rgba(255,255,255,0.1)"/>';
  var sekil4 = '<rect x="' + (320 + (h>>6) % 60) + '" y="' + (10 + (h>>6) % 40) + '" width="' + (30 + (h>>6) % 40) + '" height="' + (30 + (h>>6) % 40) + '" rx="8" fill="rgba(255,255,255,0.07)" transform="rotate(' + (h % 45) + ' 350 30)"/>';
  var tipRozeti = tip === 'kod' ? 'Kod' : tip === 'dosya' ? 'HTML' : 'Drive';
  var tipRengi = tip === 'kod' ? 'rgba(255,255,255,0.35)' : tip === 'dosya' ? 'rgba(255,255,255,0.30)' : 'rgba(255,255,255,0.25)';
  var svg = '<svg xmlns="http://www.w3.org/2000/svg" width="400" height="280">'
    + '<defs>'
    + '<linearGradient id="bg' + h + '" x1="0%" y1="0%" x2="100%" y2="100%">'
    + '<stop offset="0%" stop-color="' + ac1 + '"/>'
    + '<stop offset="100%" stop-color="' + ac2 + '"/>'
    + '</linearGradient>'
    + '<filter id="sh' + h + '"><feDropShadow dx="0" dy="4" stdDeviation="8" flood-color="rgba(0,0,0,0.15)"/></filter>'
    + '</defs>'
    + '<rect width="400" height="280" rx="18" fill="url(#bg' + h + ')" filter="url(#sh' + h + ')"/>'
    + sekil1 + sekil2 + sekil3 + sekil4
    + '<text x="200" y="100" text-anchor="middle" font-size="56">' + ikon + '</text>'
    + '<rect x="120" y="120" width="160" height="26" rx="13" fill="' + tipRengi + '"/>'
    + '<text x="200" y="138" text-anchor="middle" font-size="12" fill="white" font-weight="bold" font-family="system-ui,sans-serif">' + tipRozeti + '</text>'
    + '<text x="200" y="180" text-anchor="middle" font-size="20" font-weight="bold" fill="white" font-family="system-ui,sans-serif">'
    + baslik.replace(/</g,'&lt;') + '</text>'
    + '<text x="200" y="208" text-anchor="middle" font-size="13" fill="rgba(255,255,255,0.85)" font-family="system-ui,sans-serif">'
    + aciklama.replace(/</g,'&lt;') + '</text>'
    + '<rect x="145" y="225" width="110" height="32" rx="16" fill="rgba(255,255,255,0.3)" stroke="rgba(255,255,255,0.5)" stroke-width="1"/>'
    + '<text x="200" y="246" text-anchor="middle" font-size="13" fill="white" font-weight="bold" font-family="system-ui,sans-serif">\u25B6 Başlat</text>'
    + '</svg>';
  return 'data:image/svg+xml,' + encodeURIComponent(svg);
}

function ozelEtkinlikleriYukle() {
  if (!SUPABASE_CONFIG.url) return Promise.resolve();
  /* (v2.2) Öğrenci tarafı güvenli görünümden okur: onaylı bütün özel etkinlikler
     döner. Kapalı/tarihli etkinliğin İÇERİĞİ görünümden dönmez (icerik=null);
     portal bu kartları soluk-pasif gösterir, açılamaz. acik/acilis/kapanis
     alanları kart rozetini ve açılabilirlik kontrolünü besler.
     (v2.7.2) STATİK etkinliklerin de paneldeki aç/kapalı/tarihli durumu okunur:
     önceden listede hep açık görünüyorlardı; yönetici kapatsa bile öğrenci
     listesinde hiçbir değişiklik olmuyordu. Artık etkinlik_atama satırları
     statik listeye de uygulanır (kapalı → soluk, tarihli → geri sayım). */
  var basliklar = { apikey: SUPABASE_CONFIG.anon, Authorization: 'Bearer ' + SUPABASE_CONFIG.anon };
  var gorunum = fetch(SUPABASE_CONFIG.url + '/rest/v1/ozel_etkinlik_ogrenci?select=*&order=olusturma_tarihi', { headers: basliklar })
    .then(function (r) { return r.json(); });
  var atamalar = fetch(SUPABASE_CONFIG.url + '/rest/v1/etkinlik_atama?select=oyun_id,aktif,acilis,kapanis', { headers: basliklar })
    .then(function (r) { return r.json(); })
    .catch(function () { return []; });
  return Promise.all([gorunum, atamalar]).then(function (sonuc) {
    /* (v2.9.6) En yeni etkinlik üstte: görünüm olusturma_tarihi artan gelir;
       burada ters çevrilir. Bütün gruplar (bütün sınıf + IPT) ve aramada da
       portal bu sırayla en yeni etkinliği önce gösterir. */
    var rows = (sonuc[0] || []).slice().sort(function (a, b) {
      return String(b.olusturma_tarihi || '').localeCompare(String(a.olusturma_tarihi || ''));
    });
    var atamaMap = {};
    (sonuc[1] || []).forEach(function (a) { if (a && a.oyun_id) atamaMap[a.oyun_id] = a; });
    /* Statik etkinliklere atama durumunu uygula ('ozel:' önekli anahtarlar özel etkinliklerin) */
    ETKINLIKLER.forEach(function (e) {
      var a = atamaMap[e.id];
      if (!a) { e.acik = true; e.acilis = null; e.kapanis = null; return; }
      e.acik = a.aktif !== false;
      e.acilis = a.acilis || null;
      e.kapanis = a.kapanis || null;
    });
    OZEL_ETKINLIKLER = (rows || []).map(function (o) {
      var coz = seviyeleriCoz(o.seviyeler);
      return {
        id: 'ozel_' + o.id, ad: o.ad, aciklama: o.konu || '',
        url: null,
        onizleme: ozelOnizlemeSvg(o.ad, o.tip, o.konu),
        onizlemeData: null,
        gorsel: o.gorsel || '',
        kategoriler: coz.kategoriler, siniflar: coz.siniflar, ogretmen: coz.ogretmen,
        /* Öğretmen hiçbir seviye seçmediyse etkinlik bütün seviyelere açıktır */
        herkese: !(coz.siniflar.length || coz.kategoriler.length || coz.ogretmen),
        etiketler: ['Özel Etkinlik'], ozel: true,
        ozelTip: o.tip,
        /* Kapalıyken içerik null döner — etkinlik açılamaz */
        ozelIcerik: o.icerik || '',
        acik: o.acik !== false,
        acilis: o.acilis || null,
        kapanis: o.kapanis || null,
        nasil: ['Öğretmeniniz bu etkinliği oluşturdu.', '▶ Başlat ile açın.'],
        amac: o.konu || 'Öğretmeninizin hazırladığı özel etkinlik.',
        kazanimlar: [],
        sure: '',
        materyaller: [],
        /* (v2.9.6) En yeni önce sıralama için gizli timestamp alanı */
        _tarih: o.olusturma_tarihi || '',
        _ozelId: o.id
      };
    });
  }).catch(function () { OZEL_ETKINLIKLER = []; });
}

/* Robi maskotu (base64): portal + detay sayfası ortak görseli */
window.__ROBI_DATA__ = 'data:image/png;base64,';
